import { call, put, takeEvery } from 'redux-saga/effects';
import { createSagaMiddleware } from '@redux-saga/core';
import { configureStore } from '@reduxjs/toolkit';

// API function
const api = {
  fetchUser: (userId) => 
    fetch(`/api/users/${userId}`).then(r => r.json())
};

// Worker saga - does the actual work
function* fetchUserSaga(action) {
  try {
    // call effect: call the API function
    const user = yield call(api.fetchUser, action.payload.userId);

    // put effect: dispatch action to store
    yield put({ type: 'FETCH_USER_SUCCESS', payload: user });
  } catch (error) {
    yield put({ type: 'FETCH_USER_ERROR', payload: error.message });
  }
}

// Watcher saga - watches for actions
function* watchFetchUser() {
  // takeEvery: run fetchUserSaga for every FETCH_USER_REQUEST
  yield takeEvery('FETCH_USER_REQUEST', fetchUserSaga);
}

