import { call, put, takeLatest, fork, cancel, all } from 'redux-saga/effects';

// Example: Load user and their posts in parallel
function* loadUserData(userId) {
  const [user, posts] = yield all([
    call(api.fetchUser, userId),
    call(api.fetchPosts, userId),
  ]);
  yield put({ type: 'USER_DATA_LOADED', payload: { user, posts } });
}

// Example: takeLatest - only process the latest request
function* watchFetchUser() {
  // Cancel any previous saga if new action comes in
  yield takeLatest('FETCH_USER_REQUEST', fetchUserSaga);
}

// Example: Task cancellation
function* workflowSaga() {
  const task = yield fork(backgroundTask);

  // Wait for cancel action
  yield take('CANCEL_WORKFLOW');

  // Cancel the background task
  yield cancel(task);
}

// Example: Debouncing
function* handleSearch() {
  // debounce effect using select and delay
  const { query } = yield select(state => state.search);
  if (query) {
    yield call(delay, 500);  // Wait 500ms
    yield put({ type: 'SEARCH', payload: query });
  }
}

// takeEvery with debounce pattern
function* watchSearch() {
  yield takeLatest('SEARCH_INPUT', handleSearch);
}

import { select, call, put } from 'redux-saga/effects';

// Check auth state before making API call
function* fetchProtectedData(resourceId) {
  // Select auth token from state
  const token = yield select(state => state.auth.token);

  if (!token) {
    yield put({ type: 'AUTH_ERROR', payload: 'Not authenticated' });
    return;
  }

  // Pass token to API
  const data = yield call(
    api.fetchProtected, 
    resourceId, 
    token
  );

  yield put({ type: 'DATA_FETCHED', payload: data });
}

// Complex state selection
function* processOrder(orderId) {
  const { user, cart, settings } = yield select(state => ({
    user: state.user,
    cart: state.cart,
    settings: state.settings,
  }));

  if (cart.items.length === 0) {
    yield put({ type: 'ORDER_ERROR', payload: 'Cart is empty' });
    return;
  }

  const shippingAddress = user.addresses[settings.defaultAddress];
  yield call(api.submitOrder, { orderId, cart, shippingAddress });
}

import { runSaga } from 'redux-saga';
import { call, put } from 'redux-saga/effects';
import { fetchUserSaga, watchFetchUser } from './sagas';
import api from './api';

// Test a single saga
test('fetchUserSaga should fetch and dispatch success', async () => {
  const dispatchedActions = [];
  const fakeUser = { id: 1, name: 'Test User' };

  // Mock the API
  api.fetchUser = jest.fn().mockResolvedValue(fakeUser);

  // Run the saga
  const gen = fetchUserSaga({ payload: { userId: 1 } });

  // Step through generator
  const callEffect = gen.next();
  expect(callEffect.value).toEqual(call(api.fetchUser, 1));

  // Resume with the API result
  const putEffect = gen.next(fakeUser);
  expect(putEffect.value).toEqual(
    put({ type: 'FETCH_USER_SUCCESS', payload: fakeUser })
  );

  // Should be done
  expect(gen.next().done).toBe(true);
});

